/* Utility-evidence layers — live, view-driven Leaflet layers that fetch from
 * free crowd/agency sources for the current map view. Used by the shared layer
 * system (lib/layers.js) so they appear on BOTH the map finder and the planner.
 *
 *  - OSM Overpass: power lines / minor lines / poles / towers / substations /
 *    fire hydrants. Cached per rounded bbox; transmission vs distribution styled
 *    differently.
 *  - Mapillary: crowdsourced pole / fire-hydrant object detections (needs a free
 *    token — read from env or localStorage, never committed).
 *
 * Both are vector overlays drawn above the imagery; they refresh on map move and
 * only load once zoomed in (these sources are dense). All requests are CORS-ok.
 */
import L from "leaflet";
import { gisCache } from "./gisCache.js";
import { mapillaryRequestUrl, pickDetections } from "./mapillaryClient.js";
/* NEW-1 — the two gates below used to be module-private numbers here, which is exactly why
 * the Layers panel could not tell the owner that a checked layer was suppressed by the zoom:
 * nothing outside this file could see them. They now live in the leaf `layerZoomGate.js`
 * alongside every other gate in the app, so the panel's live "not showing at this zoom" state
 * and the runtime that actually suppresses the fetch read ONE number, never two. */
import { OSM_MIN_ZOOM, MAPILLARY_MIN_ZOOM, SOIL_BEDROCK_MIN_ZOOM } from "./layerZoomGate.js";

const OVERPASS_URL = "https://overpass-api.de/api/interpreter";
const MIN_ZOOM = OSM_MIN_ZOOM;       // OSM power/hydrant data is dense — don't fetch zoomed out
const MLY_MIN_ZOOM = MAPILLARY_MIN_ZOOM; // Mapillary bbox must be < 0.01° — high zoom only
// Overpass results ride the shared browser-local SWR cache (B75): a view paints its
// last-known-good copy instantly and refreshes in the background, and now SURVIVES a
// reload (the old in-memory Map did not). TTL = how long a copy is "fresh" before a
// background refresh fires; a stale copy is still shown immediately with its age.
const OVERPASS_TTL = 30 * 60 * 1000; // 30 min

const COL = {
  transmission: "#b91c1c", // ≥ power=line
  distribution: "#ea580c", // power=minor_line
  pole: "#f59e0b",
  substation: "#7c3aed",
  hydrant: "#dc2626",
  mly: "#0ea5e9",
};

const bboxKey = (b) => [b.s, b.w, b.n, b.e].map((x) => x.toFixed(3)).join(",");

// ---- OSM Overpass ----
export async function fetchOverpass(bounds, want, signal) {
  const bbox = `${bounds.s},${bounds.w},${bounds.n},${bounds.e}`;
  const p = [];
  if (want.lines) { p.push(`way["power"="line"](${bbox});`); p.push(`way["power"="minor_line"](${bbox});`); }
  if (want.poles) { p.push(`node["power"="pole"](${bbox});`); p.push(`node["power"="tower"](${bbox});`); }
  if (want.substations) { p.push(`way["power"="substation"](${bbox});`); p.push(`node["power"="substation"](${bbox});`); }
  if (want.hydrants) { p.push(`node["emergency"="fire_hydrant"](${bbox});`); }
  const q = `[out:json][timeout:25];(${p.join("")});out geom;`;
  const init = { method: "POST", body: "data=" + encodeURIComponent(q) };
  const r = await fetch(OVERPASS_URL, signal ? { ...init, signal } : init);
  if (!r.ok) throw new Error(`Overpass HTTP ${r.status}`);
  const j = await r.json();
  return j.elements || [];
}

function renderOverpass(els, group, opacity) {
  const op = opacity ?? 0.9;
  els.forEach((el) => {
    const tags = el.tags || {};
    if (el.type === "way" && el.geometry) {
      const pts = el.geometry.map((g) => [g.lat, g.lon]);
      if (tags.power === "substation") {
        L.polygon(pts, { className: "pf-hover-only", color: COL.substation, weight: 1.5, opacity: op, fillColor: COL.substation, fillOpacity: op * 0.18 })
          .bindTooltip("Substation (OSM)").addTo(group);
      } else {
        const minor = tags.power === "minor_line";
        L.polyline(pts, { className: "pf-hover-only", color: minor ? COL.distribution : COL.transmission, weight: minor ? 1.6 : 2.6, opacity: op, dashArray: minor ? "5 4" : null })
          .bindTooltip(`${minor ? "Distribution" : "Transmission"} line (OSM)${tags.voltage ? ` · ${tags.voltage} V` : ""}`).addTo(group);
      }
    } else if (el.type === "node" && el.lat != null) {
      const isHyd = tags.emergency === "fire_hydrant";
      const isSub = tags.power === "substation";
      const isTower = tags.power === "tower";
      const color = isHyd ? COL.hydrant : isSub ? COL.substation : COL.pole;
      L.circleMarker([el.lat, el.lon], { className: "pf-hover-only", radius: isHyd ? 4 : isTower ? 3.5 : 2.6, color, weight: 1.2, opacity: op, fillColor: color, fillOpacity: op * 0.85 })
        .bindTooltip(isHyd ? "Fire hydrant (OSM)" : isSub ? "Substation (OSM)" : isTower ? "Transmission tower (OSM)" : "Power pole (OSM)").addTo(group);
    }
  });
}

/* A view-driven Overpass overlay. `want` selects feature kinds. `onStatus(state,
 * msg)` reports loading | loaded | empty | failed for the Layers panel. */
export function overpassLayer(want, onStatus) {
  const group = L.layerGroup();
  let map = null, lastKey = null, opacity = 0.9, lastEls = [], ctrl = null;
  // Re-render at the new opacity so each feature keeps its RELATIVE fill (substations
  // faint, nodes solid) instead of being flattened to one uniform fillOpacity (B36b).
  group.setOpacity = (o) => { opacity = o; group.clearLayers(); renderOverpass(lastEls, group, opacity); };
  // Render a result set and report status, carrying the data's age (`ts`) and whether
  // it's a stale/last-good copy so the Layers panel can show "refreshed 3m ago" (B75).
  const paint = (els, ts, opts = {}) => {
    group.clearLayers(); renderOverpass(els, group, opacity); lastEls = els;
    const msg = opts.note || (els.length ? null : "No OSM features in view");
    onStatus && onStatus(els.length ? "loaded" : "empty", msg, { ts, stale: !!opts.stale });
  };
  const refresh = async () => {
    if (!map) return;
    if (map.getZoom() < MIN_ZOOM) { group.clearLayers(); lastEls = []; lastKey = "zoomed-out"; onStatus && onStatus("empty", `Zoom in to ≥ ${MIN_ZOOM} to load`); return; }
    const b = map.getBounds();
    const bb = { s: b.getSouth(), w: b.getWest(), n: b.getNorth(), e: b.getEast() };
    const key = "overpass:" + bboxKey(bb) + ":" + JSON.stringify(want);
    if (key === lastKey) return;
    lastKey = key;
    // NEW-6 — a pan SUPERSEDES whatever is still in flight, so cancel it now instead of
    // letting it land and be thrown away. This used to queue behind a `busy` flag: the
    // superseded request ran to completion (a full Overpass query, sometimes many seconds)
    // and only THEN did the view the user is actually looking at get requested. Aborting is
    // safe here because gisCache.swr writes only on success — an aborted attempt lands in
    // its catch, writes nothing, and leaves the last-good copy exactly as it was.
    if (ctrl) ctrl.abort();
    ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
    const sig = ctrl && ctrl.signal;
    // Stale-while-revalidate (B75): paint the cached copy NOW (its age is shown), then
    // refresh in the background and swap fresh data in when it returns.
    const { cached, stale, fresh } = gisCache.swr(key, () => fetchOverpass(bb, want, sig), { ttl: OVERPASS_TTL });
    if (cached) paint(cached.data, cached.ts, { stale });
    else onStatus && onStatus("loading");
    const r = await fresh;
    // B36e: the layer may have been toggled off / the map torn down while the request was
    // in flight (onRemove nulls `map`). Bail before painting or reporting status, so a stale
    // response never renders into a detached group or fires a "loaded" for an off layer.
    // A superseded request bails the same way — the newer view owns the UI now.
    if (!map || (sig && sig.aborted)) return;
    if (r.updated) paint(r.data, r.ts);
    else if (r.error && !cached) { lastKey = null; onStatus && onStatus("failed", `OSM Overpass: ${(r.error && r.error.message) || "request failed"}`); }
    else if (r.error && cached) paint(cached.data, cached.ts, { stale: true, note: "Showing last-good — refresh failed" }); // keep last-known-good
  };
  group.abortPending = () => { if (ctrl) { try { ctrl.abort(); } catch (_) {} } };
  group.onAdd = function (m) { L.LayerGroup.prototype.onAdd.call(this, m); map = m; m.on("moveend", refresh); refresh(); return this; };
  group.onRemove = function (m) { group.abortPending(); m.off("moveend", refresh); map = null; lastKey = null; L.LayerGroup.prototype.onRemove.call(this, m); };
  return group;
}

// ---- Mapillary (crowdsourced detections) ----
export const mapillaryToken = () => {
  try {
    return (import.meta.env && import.meta.env.VITE_MAPILLARY_TOKEN) || localStorage.getItem("planarfit:mapillaryToken") || "";
  } catch (_) { return ""; }
};
// Same-tab pub/sub so both LayerPanel copies (map + planner) reflect a token typed in
// either one, and pick up an externally-set token without a remount (B46).
const _mlySubs = new Set();
export const subscribeMapillaryToken = (cb) => { _mlySubs.add(cb); return () => _mlySubs.delete(cb); };
export const setMapillaryToken = (t) => {
  try { t ? localStorage.setItem("planarfit:mapillaryToken", t) : localStorage.removeItem("planarfit:mapillaryToken"); } catch (_) {}
  _mlySubs.forEach((cb) => { try { cb(mapillaryToken()); } catch (_) {} });
};

async function fetchMapillary(bounds, token, signal) {
  // Default → same-origin proxy (server injects the token); optional → user's own token
  // direct to Mapillary. The proxy 503s (no server token, e.g. a preview deploy) and a
  // static/preview build has no /api route (404) — both mean "not available here", a
  // graceful state, not a hard failure (B308).
  // `signal` (B36e) lets the layer abort a slow request the moment the layer is toggled
  // off / the map is torn down, so a stale response can't render into a detached group.
  const r = await fetch(mapillaryRequestUrl(bounds, token), signal ? { signal } : undefined);
  if (r.status === 503 || r.status === 404) { const e = new Error("Street imagery isn't available in this environment."); e.unconfigured = true; throw e; }
  if (!r.ok) throw new Error(`Mapillary HTTP ${r.status}`);
  let j;
  // A non-JSON body means the proxy isn't actually there (a preview/static build serves
  // the SPA index.html for an unknown /api path) → graceful "not available", not a failure.
  try { j = await r.json(); }
  catch (_) { const e = new Error("Street imagery isn't available in this environment."); e.unconfigured = true; throw e; }
  return pickDetections(j.data);
}

export function mapillaryLayer(onStatus) {
  const group = L.layerGroup();
  let map = null, lastKey = null, opacity = 0.95, ctrl = null;
  group.setOpacity = (o) => { opacity = o; group.eachLayer((l) => l.setStyle && l.setStyle({ opacity: o, fillOpacity: o })); };
  const refresh = async () => {
    if (!map) return;
    const token = mapillaryToken(); // empty = use the server-side proxy (B308); set = optional override
    if (map.getZoom() < MLY_MIN_ZOOM) { group.clearLayers(); lastKey = "zoomed-out"; onStatus && onStatus("empty", `Zoom in to ≥ ${MLY_MIN_ZOOM} to load`); return; }
    const b = map.getBounds();
    // clamp to < 0.01° per side (Mapillary bbox limit) around the view centre
    const c = b.getCenter(), h = 0.0045;
    const bb = { s: c.lat - h, n: c.lat + h, w: c.lng - h, e: c.lng + h };
    const key = bboxKey(bb);
    if (key === lastKey) return;
    lastKey = key;
    let feats = null; onStatus && onStatus("loading");
    // B36e: abort a slow request the moment the layer is toggled off (onRemove aborts `ctrl`),
    // so it never renders into a detached group and stops wasting the network round-trip.
    // NEW-6: the same abort now also runs on PAN SUPERSESSION. It used to queue behind a
    // `busy` flag, so a pan let the stale request finish before the current view was even
    // asked for; now the superseded request is cancelled the moment the view moves.
    if (ctrl) ctrl.abort();
    ctrl = new AbortController();
    const sig = ctrl.signal;
    try { feats = await fetchMapillary(bb, token, sig); }
    catch (e) {
      if (sig.aborted || (e && e.name === "AbortError")) return; // B36e: superseded/removed — the removal (or a newer view) owns the UI; don't reset lastKey or report status
      lastKey = null; feats = null;
      // Missing server token (preview / not yet deployed) → quiet "unconfigured", never red "failed".
      if (e && e.unconfigured) onStatus && onStatus("unconfigured", e.message);
      else onStatus && onStatus("failed", `Mapillary: ${(e && e.message) || "request failed"}`);
    }
    if (!map || sig.aborted) return; // B36e: removed / superseded mid-fetch — don't render into a detached or stale group
    if (feats === null) return;
    group.clearLayers();
    onStatus && onStatus(feats.length ? "loaded" : "empty", feats.length ? null : "No detections in view");
    feats.forEach((f) => {
      const g = f.geometry; if (!g || !g.coordinates) return;
      const [lon, lat] = g.coordinates;
      const isHyd = /hydrant/i.test(f.object_value || "");
      L.circleMarker([lat, lon], { className: "pf-hover-only", radius: 4, color: COL.mly, weight: 1.4, opacity, fillColor: isHyd ? COL.hydrant : COL.mly, fillOpacity: opacity })
        .bindTooltip(`${isHyd ? "Hydrant" : "Pole"} · crowdsourced detection (Mapillary)`).addTo(group);
    });
  };
  group.abortPending = () => { if (ctrl) { try { ctrl.abort(); } catch (_) {} } };
  group.onAdd = function (m) { L.LayerGroup.prototype.onAdd.call(this, m); map = m; m.on("moveend", refresh); refresh(); return this; };
  group.onRemove = function (m) { group.abortPending(); m.off("moveend", refresh); map = null; lastKey = null; L.LayerGroup.prototype.onRemove.call(this, m); };
  return group;
}

// ---- SSURGO depth to bedrock (B2081251) ----
// Soil is effectively static, so a copy is "fresh" for a day; the pure fetch/join lives in ssurgoBedrock.js and is
// loaded on first use so it never rides the boot bundle.
const BEDROCK_TTL = 24 * 60 * 60 * 1000;

function renderBedrock(polys, group, opacity) {
  const op = opacity ?? 0.55;
  for (const p of polys) {
    const inches = Math.round(p.depthCm / 2.54);
    const tip = `${p.muname || "Soil map unit"} · bedrock as shallow as ${inches} in (${(inches / 12).toFixed(1)} ft) in the shallowest soil of this unit (USDA SSURGO)`;
    for (const rings of p.polygons) {
      L.polygon(rings.map((r) => r.map(([lng, lat]) => [lat, lng])), {
        className: "pf-hover-only", color: p.cls.color, weight: 0.8, opacity: Math.min(1, op + 0.2), fillColor: p.cls.color, fillOpacity: op * 0.7,
      }).bindTooltip(tip, { sticky: true }).addTo(group);
    }
  }
}

/* A view-driven shallow-rock overlay. `onStatus(state, msg, extra)` as for overpassLayer. A fetch that fails
 * reports "failed" — it never paints an empty (reads-as-clear) map. */
export function bedrockLayer(onStatus) {
  const group = L.layerGroup();
  let map = null, lastKey = null, opacity = 0.55, lastPolys = [], ctrl = null;
  group.setOpacity = (o) => { opacity = o; group.clearLayers(); renderBedrock(lastPolys, group, opacity); };
  const paint = (res, ts, opts = {}) => {
    group.clearLayers(); renderBedrock(res.polys, group, opacity); lastPolys = res.polys;
    const msg = opts.note
      || (res.capped ? "Showing the first 1,500 soil map units in view — zoom in for the rest"
        : res.polys.length ? null : "No soil in view with bedrock recorded within 5 ft — not proof there is none");
    onStatus && onStatus(res.polys.length ? "loaded" : "empty", msg, { ts, stale: !!opts.stale });
  };
  const refresh = async () => {
    if (!map) return;
    if (map.getZoom() < SOIL_BEDROCK_MIN_ZOOM) { group.clearLayers(); lastPolys = []; lastKey = "zoomed-out"; onStatus && onStatus("empty", `Zoom in to ≥ ${SOIL_BEDROCK_MIN_ZOOM} to load`); return; }
    const b = map.getBounds();
    const bb = { s: b.getSouth(), w: b.getWest(), n: b.getNorth(), e: b.getEast() };
    const key = "ssurgo-bedrock:" + bboxKey(bb);
    if (key === lastKey) return;
    lastKey = key;
    if (ctrl) ctrl.abort();
    ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
    const sig = ctrl && ctrl.signal;
    let fetchBedrockView;
    try { ({ fetchBedrockView } = await import("./ssurgoBedrock.js")); }
    catch (e) { lastKey = null; onStatus && onStatus("failed", `Soil bedrock: ${(e && e.message) || "module failed to load"}`); return; }
    const { cached, stale, fresh } = gisCache.swr(key, () => fetchBedrockView(bb, { signal: sig }), { ttl: BEDROCK_TTL });
    if (cached) paint(cached.data, cached.ts, { stale });
    else onStatus && onStatus("loading");
    const r = await fresh;
    if (!map || (sig && sig.aborted)) return;
    if (r.updated) paint(r.data, r.ts);
    else if (r.error && !cached) { lastKey = null; onStatus && onStatus("failed", `USDA soils: ${(r.error && r.error.message) || "request failed"}`); }
    else if (r.error && cached) paint(cached.data, cached.ts, { stale: true, note: "Showing last-good — refresh failed" });
  };
  group.abortPending = () => { if (ctrl) { try { ctrl.abort(); } catch (_) {} } };
  group.onAdd = function (m) { L.LayerGroup.prototype.onAdd.call(this, m); map = m; m.on("moveend", refresh); refresh(); return this; };
  group.onRemove = function (m) { group.abortPending(); m.off("moveend", refresh); map = null; lastKey = null; L.LayerGroup.prototype.onRemove.call(this, m); };
  return group;
}
